# Break My Fix finding 1, generated by Tracefix: _normalize_name_in_topic_msg returns a wrong value.
# Property (issue): Two Shelly 3EM messages from the same device differing only in the emeter phase index must normalize to different topics, so the phases can be differentiated
# Quote: there's no way to either sum, or differentiate the three phases' measurements
# Run it with pytest: it fails for as long as the code breaks this property.

import re

from mqtt_exporter.main import _normalize_name_in_topic_msg


def test_break_my_fix_1() -> None:
    topic = 'shellies/shelly/emeter/0/power'
    payload = '123.45'
    # The property applies to this input: re.fullmatch(r'shellies/[A-Za-z0-9_-]+/emeter/[0-9]/[A-Za-z_]+', topic) is not None
    result = _normalize_name_in_topic_msg(topic=topic, payload=payload)
    result2 = _normalize_name_in_topic_msg(**{'topic': topic, 'payload': payload, **({"topic": '/'.join(topic.split('/')[:3] + [str((int(topic.split('/')[3]) + 1) % 10)] + topic.split('/')[4:])})})
    assert (result[0] != result2[0])
